var ph = draw.rect(CW + 6, 2 * CH + (PY - CH) + 6)
  .move(cx(3) - 3, cy(6) - 3).fill('none').stroke({ color: '#dd2222', width: 2.5 });
var arrow = draw.path('M ' + (cx(3) + CW / 2 - 20) + ' ' + (cy(7) + CH + 4) +
  ' C ' + (cx(3) - 30) + ' ' + (cy(7) + CH + 55) + ', ' + (FX0 - 20) + ' ' + (FY0 - 30) +
  ', ' + (FX0 + 4) + ' ' + (FY0 - 6))
  .fill('none').stroke({ color: '#dd2222', width: 2.5 });
var mk = draw.marker(12, 12, function (add) { add.path('M0,0 L12,6 L0,12 z').fill('#dd2222'); });
arrow.marker('end', mk);

// ---- selection / info ----
var RULES = {
  cation: function (g) { return 'Loses ' + g + ' electron' + (g > 1 ? 's' : '') + ' to reach the previous noble gas.'; },
  anion: function (g) { return 'Gains ' + (18 - g) + ' electron' + (g < 17 ? 's' : '') + ' to reach the next noble gas.'; }
};
function describe(c) {
  var name = c.labels.length ? c.labels.join(' / ') : (c.fblock ? (c.type === 'lan' ? 'Lanthanides' : 'Actinides') : 'Group ' + c.g);
  var cfg = '', rule = '';
  if (c.type === 'tm') rule = 'Transition metal: variable charges (d-electrons lost in differing numbers) — group number does not predict the ion.';
  else if (c.type === 'lan' || c.type === 'act') rule = 'f-block element: commonly forms +3 ions; group-3 position, inner transition metal.';
  else if (c.type === 'g18') rule = 'Noble gas: full outer shell — forms no ions.';
  else if (c.type === 'h') rule = 'Hydrogen is special: can form H⁺ or H⁻.';
  else if (c.g <= 2 || c.g === 13) rule = RULES.cation(c.g <= 2 ? c.g : c.g - 10);
  else rule = RULES.anion(c.g);
  if (c.labels.length && CONFIGS[c.labels[0]]) cfg = 'Electron configuration of ' + c.labels[0] + ': ' + CONFIGS[c.labels[0]] + '.';
  return { title: name, body: (cfg ? cfg + ' ' : '') + rule };
}
function selectCell(c) {
  if (selectRect) selectRect.remove();
  selectRect = draw.rect(CW + 6, CH + 6).move(c.rect.x() - 3, c.rect.y() - 3)
    .fill('none').stroke({ color: '#ff8800', width: 3 }).radius(3);
  var d = describe(c);
  document.getElementById('elemPanel').innerHTML = '<b>' + d.title + '</b><br>' + d.body;
  showPopup(d.title, d.body);
}

// ---- interactions ----
var GRP_DESCR = { 1:'Group 1 → +1 cations (alkali metals)', 2:'Group 2 → +2 cations (alkaline earths)',
  13:'Group 13 → +3 cations (e.g. Al³⁺)', 14:'Group 14 → usually covalent; C⁴⁻ formal', 15:'Group 15 → −3 anions',
  16:'Group 16 → −2 anions', 17:'Group 17 → −1 anions (halides)', 18:'Group 18 → noble gases: no ions' };
function update_groupSweep(v) {
  if (highlightRect) highlightRect.remove();
  highlightRect = null;
  var top = 1e9, bot = -1e9, found = false;
  for (var i = 0; i < cells.length; i++) {
    var c = cells[i];
    if (c.fblock) continue;
    if (c.g === v) { found = true; top = Math.min(top, c.rect.y()); bot = Math.max(bot, c.rect.y() + CH); }
  }
  if (found) {
    highlightRect = draw.rect(CW + 10, bot - top + 10).move(cx(v) - 5, top - 5)
      .fill('none').stroke({ color: '#ff8800', width: 3 }).radius(4);
  }
  var d = GRP_DESCR[v] || ('Group ' + v + ' → transition metal: variable charges, not predicted by group');
  document.getElementById('grpInfo').textContent = d;
}
function toggle_colorScheme(on) {
  colorByCharge = on;
  for (var i = 0; i < cells.length; i++) cells[i].rect.fill(fillFor(cells[i]));
  document.getElementById('elemPanel').innerHTML = on
    ? '<b>Charge-value coloring</b><br>Warm = cations (left), cool = anions (right), gray = zero or variable (d/f-block, noble gases).'
    : 'Click any cell to see its ion, electron configuration, and the group rule.';
}

// ---- demo steps ----
var STEPS = [
  { title: 'Alkali and alkaline earth metals',
    narration: 'Sweep Groups 1 and 2: every element loses electrons equal to its group number, forming +1 and +2 cations to reach the previous noble-gas configuration.',
    group: 1, charge: false },
  { title: 'Transition metals break the rule',
    narration: 'Groups 3–12: charges become variable (Fe²⁺/Fe³⁺, Cu⁺/Cu²⁺) because d-electrons are lost in differing numbers — group position no longer reliably predicts the ion.',
    group: 8, charge: false },
  { title: 'Nonmetal anions and noble gases',
    narration: 'Groups 15–18: nonmetals gain electrons to reach the next noble gas (N³⁻, O²⁻, F⁻); the charge equals how many groups they lie left of Group 18 — and noble gases form no ions.',
    group: 16, charge: false },
  { title: 'Recolor by charge',
    narration: 'Charge-value coloring shows the whole trend at a glance: cations on the left, anions on the right, a variable middle, and a zero-charge noble-gas column.',
    group: 18, charge: true }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  var s = STEPS[stepIdx];
  var inp = document.getElementById('groupSweepInput');
  inp.value = s.group;
  document.getElementById('groupSweepVal').value = s.group;
  update_groupSweep(s.group);
  var cb = document.getElementById('colorSchemeInput');
  cb.checked = s.charge;
  toggle_colorScheme(s.charge);
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + STEPS.length;
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

